const List<(String, String, String)> _apiNotes = [
    ("Krebs cycle", "Citric acid cycle", "Acetyl-CoA enters the cycle."),
    ("Calvin cycle", "", "Carbon fixation in the stroma."),
    ("Cell cycle checkpoints", "Mitosis control", "G1, S, G2, M."),
    ("Glycolysis", "Before the Krebs cycle", "Glucose to pyruvate."),
    ("Unrelated", "", "Nothing here."),
];

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  final cases = jsonDecode(_cases) as Map<String, dynamic>;

  group('SequenceMatcher.ratio parity', () {
    for (final c in cases['ratio'] as List) {
      final [a as String, b as String, expected as num] = c as List;
      test('ratio(${jsonEncode(a)}, ${b.length} chars)', () {
        expect(sequenceRatio(a, b), closeTo(expected.toDouble(), 1e-12));
      });
    }
  });

  group('note_search_score parity', () {
    for (final c in cases['score'] as List) {
      final [title as String, description as String, content as String,
          query as String, expected] = c as List;
      test('score(${jsonEncode(query)}) on ${jsonEncode(title)}', () {
        final got = noteSearchScore(
            title: title, description: description, content: content, query: query);
        if (expected == null) {
          expect(got, isNull);
        } else {
          final [score as num, fuzzy as num] = expected as List;
          expect(got, isNotNull);
          expect(got!.$1, closeTo(score.toDouble(), 1e-9));
          expect(got.$2, closeTo(fuzzy.toDouble(), 1e-12));
        }
      });
    }
  });

  test('GET /notes/?q= ranks as the backend does', () async {
    final (c, _) = await folderApp();
    for (final (title, description, content) in _apiNotes) {
      await createNote(c,
          title: title, content: content, extra: {'description': description});
    }
    final r = await callApi(c, 'GET', '/notes/?q=${Uri.encodeQueryComponent("krebs cycle")}');
    expect(r.statusCode, 200, reason: r.body);
    expect([for (final n in listOf(r)) n['title']], ["Krebs cycle", "Glycolysis", "Calvin cycle", "Cell cycle checkpoints"]);
  });
}
